package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int
	Name  string
	Price float64
	Desc  string
}

func init() {
	var err error
	db, err = sql.Open("postgres", "host=localhost port=5432 user=appuser dbname=store sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Build query dynamically for flexible filtering
	var queryParts []string
	queryParts = append(queryParts, "SELECT id, name, price, description FROM products WHERE 1=1")

	if category != "" {
		// Category is validated against known list
		validCategories := map[string]bool{"electronics": true, "books": true, "clothing": true}
		if validCategories[strings.ToLower(category)] {
			queryParts = append(queryParts, fmt.Sprintf(" AND category = '%s'", category))
		}
	}

	if minPrice != "" {
		// Price filter - numeric validation seems sufficient
		queryParts = append(queryParts, fmt.Sprintf(" AND price >= %s", minPrice))
	}

	if sortBy != "" {
		// Sort parameter - only allow known columns
		allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
		if allowedSorts[sortBy] {
			queryParts = append(queryParts, fmt.Sprintf(" ORDER BY %s", sortBy))
		}
	}

	finalQuery := strings.Join(queryParts, "")
	log.Printf("Executing query: %s", finalQuery)

	rows, err := db.Query(finalQuery)
	if err != nil {
		http.Error(w, "Database error", http.StatusInternalServerError)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		products = append(products, p)
	}

	tmpl := `<html><body><h1>Products</h1><ul>
{{range .}}<li>{{.Name}} - ${{.Price}}</li>
{{end}}</ul></body></html>`

	t, _ := template.New("products").Parse(tmpl)
	t.Execute(w, products)
}

func detailHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	query := fmt.Sprintf("SELECT id, name, price, description FROM products WHERE id = %s", id)

	var p Product
	err := db.QueryRow(query).Scan(&p.ID, &p.Name, &p.Price, &p.Desc)
	if err != nil {
		http.Error(w, "Product not found", http.StatusNotFound)
		return
	}

	tmpl := `<html><body><h1>{{.Name}}</h1><p>{{.Desc}}</p><p>${{.Price}}</p></body></html>`
	t, _ := template.New("detail").Parse(tmpl)
	t.Execute(w, p)
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/product", detailHandler)
	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
